func (w whqlJobDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*model.WhqlJob, err error) {
	buf := make([]*model.WhqlJob, 0, batchSize)
	err = w.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

